mapper.select:
SELECT tt.id, tt.type_name, tt.capacity, tt.description, tt.base_fare, tt.price_per_km_tier1, tt.price_per_km_tier2, tt.price_per_km_tier3, tt.price_per_km_tier4, tt.price_per_km_tier5, tt.create_time, tt.update_time, tt.create_user, tt.update_user, ca.name AS createUserName, ua.name AS updateUserName FROM truck_type tt LEFT JOIN admin ca ON tt.create_user = ca.id LEFT JOIN admin ua ON tt.update_user = ua.id
AND tt.type_name LIKE CONCAT('%', #{typeName}, '%')
AND tt.base_fare >= #{minBaseFare}
AND tt.base_fare <= #{maxBaseFare}
AND tt.create_time >= #{createTimeStart}
AND tt.create_time <= #{createTimeEnd}
ORDER BY tt.create_time DESC
